    <div className=\"widget-body\"><div className=\"chart-heading\"><div><div className=\"chart-title-row\"><Text variant=\"header-2\" as=\"h2\">{sales ? 'Динамика продаж' : 'Время ответа API'}</Text><span className=\"subtle-badge\">{sales ? 'Выручка' : 'Production'}</span></div><p className=\"chart-subtitle\">{sales ? 'Как менялась выручка в выбранном периоде' : 'Каждое измерение — для полной картины работы сервиса'}</p></div><SegmentedRadioGroup size=\"m\" value={range} onUpdate={onRangeChange} options={rangeOptions} aria-label=\"Период графика\"/></div>
