    <div className="chart-container" aria-label={sales ? '"'Линейный график выручки' : 'Плотный временной ряд мониторинга'}>
      {loading ? <ChartState kind=\"loading\"/> : error ? <ChartState kind=\"error\" message={error} retry={onRefresh}/> : empty ? <ChartState kind=\"empty\" message={hidden.length === data.series.length ? 'Выберите серию под графиком' : undefined}/> : <ChartKit key={"'`${mode}-${retry}`} type={sales ? '"'gravity-charts' : 'yagr'} id=\"pulse-chart\" data={chartData} renderPluginLoader={() => <ChartState kind=\"loading\"/>} renderError={({resetError}) => <ChartState kind=\"error\" message=\"Не удалось загрузить график\" retry={() => {resetError(); setRetry((n) => n + 1);}}/>/>}
    </div>
    <div className=\"chart-legend\">{data.series.map((series) => <Button key={series.id} view=\"flat\" size=\"s\" className={"'`legend-button ${hidden.includes(series.id) ? '"'legend-hidden' : ''}"'`} aria-pressed={!hidden.includes(series.id)} onClick={() => toggleSeries(series.id)}><span className={`legend-line ${series.comparison ? '"'legend-comparison' : ''}"'`}/>{series.name}</Button>)}<span className="chart-hint">{sales ? '"'Наведите на график, чтобы увидеть детали' : 'Выделите область для увеличения · двойной клик для сброса'}</span></div>
    <div className=\"insight\"><span className=\"insight-symbol\">{sales ? '↗' : '∿'}</span><p>{sales ? <><strong>Продажи набирают темп.</strong> Выручка на {stats.growth.toFixed(1).replace('.', ',')}% выше предыдущего периода.</> : <><strong>Сервис работает стабильно.</strong> Среднее время ответа — {number(stats.average)} мс за выбранный период.</>}</p><span className=\"insight-label\">{sales ? 'Тренд периода' : 'Состояние сервиса'}</span></div>
