    <div className=\"widget-footer\"><span><span className=\"status-dot\"/>Демонстрационные данные</span><span aria-live=\"polite\">Обновлено {updatedAt?.toLocaleTimeString('ru-RU', {hour: '2-digit', minute: '2-digit'}) ?? '—'} <span className=\"footer-dot\">·</span> {number(data.timeline.length)} точек</span></div>
  </section>;
}
